policies:
create policy messages_insert on public.conversation_messages as permissive for insert to authenticated with check (((sender_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM conversation_participants
  WHERE ((conversation_participants.conversation_id = conversation_messages.conversation_id) AND (conversation_participants.user_id = auth.uid()))))));

create policy messages_select on public.conversation_messages as permissive for select to authenticated using ((EXISTS ( SELECT 1
   FROM conversation_participants
  WHERE ((conversation_participants.conversation_id = conversation_messages.conversation_id) AND (conversation_participants.user_id = auth.uid())))));

create policy participants_insert on public.conversation_participants as permissive for insert to authenticated with check (((user_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'compete_admin'::text])))))));

create policy participants_select on public.conversation_participants as permissive for select to authenticated using (((user_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'compete_admin'::text])))))));

create policy "Admins can view all reports" on public.reports as permissive for select to authenticated using ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'compete_admin'::text]))))));

create policy "Admins can update any tournament" on public.tournaments as permissive for update to public using ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'compete_admin'::text]))))));

create policy "Anyone can read tournaments" on public.tournaments as permissive for select to public using (((status = ANY (ARRAY['active'::text, 'completed'::text, 'cancelled'::text])) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'compete_admin'::text])))))));
